147	        return this.namesakeCount;
148	    }
149	
150	    public void setNamesakeCount(Integer namesakeCount) {
151	        this.namesakeCount = namesakeCount;
152	    }
153	
154	    public String getPostcode() {
155	        return this.postcode;
156	    }
157	
158	    public void setPostcode(String postcode) {
159	        this.postcode = postcode;
160	    }
161	
162	    /** The highest membership level assignable on creation; level 4 is reserved for tenure. */
163	    public static final int MAX_MEMBERSHIP_LEVEL = 3;
164	
165	    /**
166	     * The owner's numeric membership level, computed from stored fields: it starts at 1, gains 1
167	     * when an email is present, gains 1 when {@code namesakeCount} is 0, and is capped at
168	     * {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is reserved for tenure).
169	     */
170	    public int getMembershipLevel() {
171	        int level = 1;
172	        if (this.email != null && !this.email.isEmpty()) {
173	            level++;
174	        }
175	        if (this.namesakeCount != null && this.namesakeCount == 0) {
176	            level++;
177	        }
178	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
179	    }
