181	    /**
182	     * The derived identity key used to detect duplicate owners: the (already normalized) telephone,
183	     * the email or empty, and the {@code householdId} or empty, joined with {@code '|'}. This single
184	     * key consolidates the former separate telephone, email and household duplicate rules — two
185	     * owners are duplicates only when their whole identity keys are equal. Because the telephone is
186	     * part of the key, two members of the same household (same {@code householdId}) with different
187	     * telephones have different keys and are both allowed.
188	     */
189	    public String getIdentityKey() {
190	        String tel = this.telephone == null ? "" : this.telephone;
191	        String mail = this.email == null ? "" : this.email;
192	        String household = this.householdId == null ? "" : this.householdId;
