230	        this.pets = new HashSet<>(pets);
231	    }
232	
233	    public void addPet(Pet pet) {
234	        getPetsInternal().add(pet);
235	        pet.setOwner(this);
236	    }
237	
238	    /**
239	     * Return the Pet with the given name, or null if none found for this Owner.
240	     *
241	     * @param name to test
242	     * @return true if pet name is already in use
243	     */
244	    public Pet getPet(String name) {
245	        return getPet(name, false);
246	    }
247	
248	    /**
249	     * Return the Pet with the given name, or null if none found for this Owner.
250	     *
251	     * @param name to test
252	     * @return true if pet name is already in use
253	     */
254	    public Pet getPet(String name, boolean ignoreNew) {
255	        name = name.toLowerCase();
256	        for (Pet pet : getPetsInternal()) {
257	            if (!ignoreNew || !pet.isNew()) {
258	                String compName = pet.getName();
259	                compName = compName.toLowerCase();
260	                if (compName.equals(name)) {
261	                    return pet;
262	                }
263	            }
264	        }
265	        return null;
266	    }
267	
268	    public Pet getPet(Integer petId) {
269	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
270	    }
271	
272	    @Override
273	    public String toString() {
274	        return new ToStringCreator(this)
275	
276	            .append("id", this.getId())
277	            .append("new", this.isNew())
278	            .append("lastName", this.getLastName())
279	            .append("firstName", this.getFirstName())
280	            .append("address", this.address)
281	            .append("city", this.city)
282	            .append("telephone", this.telephone)
283	            .toString();
284	    }
285	}
